import React from 'react';
import ReactDOM from 'react-dom';
import { Form, Input } from '@alifd/next';

const FormItem = Form.Item;

const BizFormItem = (props) => {
    const { children, label, ...others } = props;
    return (
        <FormItem
            label={<span>{label}<Icon type="help" size="small" /></span>}
            errorMessageLabel={label}
            {...others}
        >
            {children}
        </FormItem>
    );
};

class Demo extends React.Component {
    render() {
        return (
            <Form useLabelForErrorMessage colon>
                <BizFormItem
                    label="Account"
                    required
                    name="valUsername"
                >
                    <Input placeholder="Input frank" />
                </BizFormItem>
                <FormItem
                    label="Email"
                    required
                    requiredTrigger="onBlur"
                    format="email"
                    name="valEmail"
                >
                    <Input placeholder="Both trigger onBlur and onChange" />
                </FormItem>
            </Form>
        );
    }
}

ReactDOM.render(<Demo />, document.getElementById('root'));
